    "src/interface/IActionHandler.sol": {
      "content": "// SPDX-License-Identifier: UNLICENSED
pragma solidity 0.8.28;

import {EngineType, OrderSide} from "../share/Enums.sol";
import {ActionId} from "../share/UserDefinedTypes.sol";

interface IActionHandler {
    // --- Events --- //

    /// @notice Emitted when a deposit has been finalized.
    event DepositFinalized(
        address indexed sender,
        bytes32 indexed subaccount,
        address token,
        uint256 amount,
        uint128 fee,
        uint256 balance,
        bytes32 initiatedTxHash,
        uint32 initiatedLogIdx,
        uint64 messageIdx
    );

    /// @notice Emitted when a token conversion is finalized.
    event ConvertFinalized(
        address indexed account,
        bytes32 indexed subaccount,
        bytes32 indexed convertDigest,
        address fromToken,
        address toToken,
        uint128 fromAmount,
        uint128 toAmount,
        uint128 fee,
        uint64 finalizedTimestamp,
        uint64 messageIdx
    );

    /// @notice Emitted when signer is linked to the subaccount (i.e. msg.sender).
    event SignerLinked(
        address indexed sender,
        bytes32 indexed subaccount,
        address indexed signer,
        uint64 linkedTimestamp,
        uint64 messageIdx
    );

    /// @notice Emitted when signer linkage is rejected i.e. the signer has deposited (is already an account).
    event SignerLinkRejected(
        address indexed sender,
        bytes32 indexed subaccount,
        address indexed signer,
        uint64 rejectedTimestamp,
        uint64 messageIdx
    );

    /// @notice Emitted when signer is revoked from the subaccount (i.e. msg.sender).
    event SignerRevoked(
        address indexed sender,
        bytes32 indexed subaccount,
        address indexed signer,
        uint64 revokedTimestamp,
        uint64 messageIdx
    );

    /// @notice Emitted when signer revocation is rejected (i.e. signature validation failed).
    event SignerRevokeRejected(
        address indexed sender,
        bytes32 indexed subaccount,
        address indexed signer,
        uint64 rejectedTimestamp,
        uint64 messageIdx
    );

    /// @notice Emitted when a subaccount initiated a withdrawal.
    event WithdrawInitiated(
        address indexed account,
        bytes32 indexed subaccount,
        bytes32 indexed withdrawDigest,
        address token,
        uint256 amount,
        uint128 fee,
        uint64 initiatedTimestamp,
        uint64 messageIdx
    );

    /// @notice Emitted when a batch is processed.
    event ActionsProcessed(ActionId firstActionId, ActionId lastActionId, uint256 length);

    // --- ActionTypes --- //

    struct FinalizeDepositAction {
        address account;
        bytes32 subaccount;
        address token;
        uint256 amount;
        bytes32 initiatedTxHash;
        uint32 initiatedLogIdx;
        uint64 messageIdx;
    }

    struct InitiateWithdrawAction {
        InitiateWithdrawMessage message;
        bytes signature;
        uint128 fee;
        uint64 messageIdx;
    }

    struct InitiateWithdrawMessage {
        address account;
        bytes32 subaccount;
        address token;
        uint256 amount;
        uint64 nonce;
        uint64 signedAt;
        bytes32 destinationAddress;
        uint32 destinationEndpointId;
    }

    struct ConvertTokenAction {
        ConvertTokenMessage message;
        bytes signature;
        uint128 fee;
        uint128 toAmount;
        uint64 messageIdx;
    }

    struct ConvertTokenMessage {
        address sender;
        bytes32 subaccount;
        address fromToken;
        address toToken;
        uint128 amount;
        uint64 nonce;
        uint64 signedAt;
    }

    struct LinkSignerAction {
        LinkSignerMessage message;
        bytes signature;
        bytes signerSignature;
        uint64 messageIdx;
    }

    struct LinkSignerMessage {
        address sender;
        address signer;
        bytes32 subaccount;
        uint64 nonce;
        uint64 signedAt;
    }

    struct MatchOrdersAction {
        TradeOrder maker;
        TradeOrder taker;
        bytes makerSignature;
        bytes takerSignature;
        uint128 makerFee;
        uint128 takerFee;
        int128 makerRealizedPnl;
        int128 takerRealizedPnl;
        uint128 fillQuantity;
        uint128 fillNotional;
        uint64 messageIdx;
    }

    struct RevokeLinkedSignerAction {
        RevokeLinkedSignerMessage message;
        bytes signature;
        uint64 messageIdx;
    }

    struct RevokeLinkedSignerMessage {
        address sender;
        address signer;
        bytes32 subaccount;
        uint64 nonce;
        uint64 signedAt;
    }

    struct TradeOrder {
        address sender;
        bytes32 subaccount;
        uint128 quantity;
        uint128 price;
        bool reduceOnly;
        OrderSide side;
        EngineType engineType;
        uint32 productId;
        uint64 nonce;
        uint64 signedAt;
    }

    struct UpdateFundingAction {
        uint32 productId;
        int128 fundingDeltaUsd;
        uint64 messageIdx;
    }

    struct FinalizePerpProductUpdateAction {
        uint32 productId;
        uint16 maxLeverage;
        uint128 maxQuantity;
        uint128 maxOpenInterestUsd;
        uint128 maxPositionNotionalUsd;
        uint64 messageIdx;
    }

    struct UpdatePositionFeeAction {
        uint32 productId;
        uint128 positionFeeDeltaUsd;
        uint256 liquidatorCreditAmount;
        uint64 messageIdx;
    }

    struct RealizeFundingAction {
        address account;
        bytes32 subaccount;
        uint32[] productIds;
        uint64 messageIdx;
    }

    struct RealizePnlAction {
        address account;
        bytes32 subaccount;
        uint32 productId;
        int128 costDelta;
        uint64 messageIdx;
    }

    struct InitiatePerpProductDelistAction {
        uint32 productId;
        uint64 messageIdx;
        uint64 pythFee;
        bytes pythPriceUpdate;
    }

    struct FinalizePerpProductDelistAction {
        uint32 productId;
        uint64 messageIdx;
    }

    struct PerpProductDelistPositionSettlementAction {
        address account;
        bytes32 subaccount;
        uint32 productId;
        int128 realizedPnl;
        uint64 messageIdx;
    }

    /// @notice Given a list of signed offchain actions, submit and process (sequencer only).
    /// @param actions Byte array of actions to process
    function processActions(bytes[] calldata actions) external payable;

    /// @notice Simulates `processActions` and always reverts after processing.
    /// @param actions Byte array of actions to simulate.
    /// @param minGasLeft Minimum gas that must remain after each action. Disables if zero.
    function processActionsDryRun(bytes[] calldata actions, uint256 minGasLeft) external payable;

    /// @notice Finalizes a revoked signer when signature verification failed onchain.
    /// @param message Revocation message data to finalize
    function finalizeRevokeLinkedSigner(RevokeLinkedSignerMessage calldata message) external;
}
"
    },
    "src/interface/IDeleverage.sol": {
      "content": "// SPDX-License-Identifier: UNLICENSED
pragma solidity 0.8.28;

import {ActionId} from "../share/UserDefinedTypes.sol";

interface IDeleverage {
    // --- Events --- //

    /// @notice Emitted when a position is reduced due to deleveraging.
    event PositionDeleveraged(
        uint32 indexed productId,
        address indexed account,
        bytes32 indexed subaccount,
        int128 sizeDelta,
        int128 realizedPnl,
        uint128 notional,
        uint64 messageIdx
    );

    /// @notice Emitted when the liquidator bankruptcy check failed but within tolerance.
    event DeleverageLiquidatorBankruptcyCheckMismatch(ActionId id, int256 equity, uint256 tolerance);

    // --- Structs --- //

    /// @notice Internal struct for deleverage match processing (full-size types).
    struct DeleverageUserMatch {
        /// Onchain productId for this match.
        uint32 productId;
        /// Size delta to deleverage from both positions (from the perspective of the user).
        int128 sizeDelta;
        /// Notional of the match `size x price` transferred from liquidator (absolute notional).
        uint128 notional;
        /// Realized PnL for the user from position reduction.
        int128 userRealizedPnl;
        /// Realized PnL for the liquidator from position reduction.
        int128 liquidatorRealizedPnl;
    }

    /// @notice Realized pnl data for a pre-processed user/product pair.
    struct RealizePnl {
        /// Onchain productId of the position being adjusted.
        uint32 productId;
        /// Signed change applied to the position cost to realize PnL.
        int128 costDelta;
    }

    /// @notice Packed user match for deleverage action - uses smaller types to minimize calldata.
    struct DeleverageUserMatchPacked {
        /// Index into the products array (max 65535 products).
        uint16 productIndex;
        /// Size delta to deleverage (in gwei precision, int64 sufficient for most positions).
        int64 sizeDelta;
        /// Notional of the match (in gwei precision).
        uint64 notional;
        /// Realized PnL for the user.
        int64 userRealizedPnl;
        /// Realized PnL for the liquidator.
        int64 liquidatorRealizedPnl;
    }

    /// @notice User struct for deleverage action.
    struct DeleverageUser {
        /// Address of the account being deleveraged.
        address account;
        /// Subaccount of the account being deleveraged.
        bytes32 subaccount;
        /// All deleverage matches for this user.
        DeleverageUserMatchPacked[] matches;
    }

    /// @notice User chunk for deleverage action with compensation.
    struct DeleverageUserChunk {
        /// Address of the account being deleveraged.
        address account;
        /// Subaccount of the account being deleveraged.
        bytes32 subaccount;
        /// All deleverage matches for this user.
        DeleverageUserMatchPacked[] matches;
        /// Realized pnl snapshots provided before position reduction.
        RealizePnl[] preRealizations;
        /// Number of pre-realizations that should be applied before each deleverage match in `matches`.
        uint16[] preRealizationCounts;
    }

    /// @notice Individual Pyth update payload and fee for deleverage.
    struct DeleveragePythUpdate {
        /// Pyth price update blob.
        bytes pythPriceUpdate;
        /// Fee in wei required by Pyth to perform this price validation.
        uint64 pythFee;
    }

    /// @notice Deleverage action with individual Pyth updates per product and packed encoding.
    struct DeleverageLiquidatorAction {
        /// Individual Pyth price update + fee per product (one update per productId).
        DeleveragePythUpdate[] pythPriceUpdates;
        /// Product IDs in the same order as pythPriceUpdates.
        uint32[] productIds;
        /// User deleverages with packed matches.
        DeleverageUser[] users;
        /// Matching engine message correlation index.
        uint64 messageIdx;
    }

    /// @notice Deleverage action with pre-realized PnL chunks to support liquidation sequencing.
    struct DeleverageLiquidatorWithCompensationAction {
        /// Individual Pyth price update + fee per product (one update per productId).
        DeleveragePythUpdate[] pythPriceUpdates;
        /// Product IDs in the same order as pythPriceUpdates.
        uint32[] productIds;
        /// User chunks containing matches and pre-realized pnl data.
        DeleverageUserChunk[] users;
        /// Matching engine message correlation index.
        uint64 messageIdx;
    }

    /// @notice Performs deleveraging by reducing liquidator positions against user positions.
    /// @dev Uses individual Pyth updates per product and packed struct encoding.
    /// @param id action identifier for the deleverage (useful when part of a batch operation).
    /// @param actionData the bytes of the packed payload excluding the action header.
    function deleverageLiquidator(ActionId id, bytes calldata actionData) external payable;
}

interface IDeleverageWithCompensation {
    /// @notice Performs deleveraging with pre-realized PnL per user chunk, reducing liquidator positions against user positions.
    /// @dev Uses the packed compensation wire format with pre-realization payloads.
    /// @param id action identifier for the deleverage (useful when part of a batch operation).
    /// @param actionData the full packed compensation action bytes, including the action header.
    function deleverageLiquidatorWithCompensation(ActionId id, bytes calldata actionData) external payable;
}
"
    },
