    "src/interface/IExchangeGateway.sol": {
      "content": "// SPDX-License-Identifier: UNLICENSED
pragma solidity 0.8.28;

import {IPerpEngine} from "../interface/IPerpEngine.sol";
import {Deposit} from "../lib/storage/Deposit.sol";
import {FeeSchedule} from "../lib/storage/FeeSchedule.sol";
import {PerpPosition} from "../lib/storage/PerpPosition.sol";
import {PerpProduct} from "../lib/storage/PerpProduct.sol";
import {Token} from "../lib/storage/Token.sol";
import {Withdraw} from "../lib/storage/Withdraw.sol";
import {ActionType, EngineType} from "../share/Enums.sol";

interface IExchangeGateway {
    // --- Events --- //

    /// @notice Emitted when the exchange pause status has transitioned state.
    event ExchangePauseUpdated(address indexed account, bool isPaused);

    /// @notice Emitted when a public indexer ping is recorded.
    /// @dev This is a permissionless offchain indexing aid, not an authenticated liveness signal.
    event Ping(address indexed sender, uint64 timestamp);

    /// @notice Emitted when a fee has been credited to a collector, but is yet to be transferred.
    event FeeAccrued(
        address indexed account,
        bytes32 indexed subaccount,
        address token,
        uint256 feeAmount,
        uint256 balance,
        uint64 messageIdx
    );

    /// @notice Emitted when a subaccount's position is transferred to another subaccount
    event PositionTransferred(
        uint32 indexed productId,
        EngineType indexed engineType,
        address accountFrom,
        bytes32 subaccountFrom,
        address accountTo,
        bytes32 subaccountTo,
        int128 amount
    );

    /// @notice Emitted when an address registry record is updated.
    event RegistryRecordUpdated(bytes32 indexed name, address indexed record);

    // --- Multicall --- //

    /// @notice Batches multiple owner calls into a single atomic transaction.
    /// @dev Uses `address(this).delegatecall` so that `msg.sender` is preserved for access-control checks.
    /// @param data Array of ABI-encoded function calls to execute on the gateway.
    /// @return results Array of ABI-encoded return values from each call.
    function multicall(bytes[] calldata data) external returns (bytes[] memory results);

    // --- AddressRegistry --- //

    /// @notice Update the exchange's address registry by `name` and `record`.
    /// @param name Name of the record we want to update or add
    /// @param record Address of the contract we want to set
    function updateRegistryRecord(bytes32 name, address record) external;

    // --- Ping --- //

    /// @notice Records a public exchange ping for offchain indexers.
    /// @dev Permissionless by design: any sender can emit this log so indexers can observe a recent gateway event
    ///      without relying on empty-block assumptions or external checkpointing.
    function ping() external;

    // -- EmergencyPause -- //

    /// @notice Prevents deposits, withdrawals and trading actions on the exchange.
    function emergencyPause() external;

    /// @notice Enables deposits, withdrawals and trading actions on the exchange.
    function emergencyUnpause() external;

    // --- PerpEngine --- //

    /// @notice Registers a product (i.e. trading pair) against an engine for trading.
    /// @param params AddProductParams struct for product configuration
    function registerPerpProduct(IPerpEngine.RegisterPerpProductParams calldata params) external returns (uint32);

    /// @notice Updates an existing product (i.e. trading pair).
    /// @param params struct for updating product configuration
    function updatePerpProduct(IPerpEngine.UpdatePerpProductParams calldata params) external;

    /// @notice Updates an existing perp product's Pyth feed id.
    function updatePerpProductPythFeedId(uint32 productId, uint32 pythFeedId) external;

    /// @notice Activates a pending perp product.
    function activatePerpProduct(uint32 productId) external;

    /// @notice Initiates a perp product delist. Offchain engine uses the latest available mark price to delist.
    /// @param productId Id of the perp product to delist
    function delistPerpProduct(uint32 productId) external;

    // --- PerpEngineViews --- //

    /// @notice Returns a perp product by its `productId`.
    /// @param productId Id of the targeted perp product
    function getPerpProduct(uint32 productId) external view returns (PerpProduct.Info memory);

    /// @notice Returns the pending perp product update for `productId`, if one exists.
    /// @param productId Id of the targeted perp product
    function getPendingPerpProductUpdate(uint32 productId)
        external
        view
        returns (IPerpEngine.UpdatePerpProductParams memory);

    /// @notice Returns the next perp product id that will be assigned on registration.
    function getNextPerpProductId() external view returns (uint32);

    /// @notice Returns a perp position by its `sender` and `subaccount` in `product`.
    /// @param sender Address of the account owner
    /// @param subaccount Subaccount the position belongs to
    /// @param productId Product the position was opened on
    function getPerpPosition(address sender, bytes32 subaccount, uint32 productId)
        external
        view
        returns (PerpPosition.Data memory);

    // --- GatewayViews --- //

    /// @notice Returns the balance of an account's subaccount for a specific token in D9.
    /// @param account Address of the account owner
    /// @param subaccount Subaccount belonging to the account
    /// @param token Address of token to check balances of
    function getAccountBalance(address account, bytes32 subaccount, address token) external view returns (uint256);

    /// @notice Returns whether the account's subaccount has been registered.
    /// @param account Address of the account owner
    /// @param subaccount Subaccount belonging to the account
    function getAccountHasRegistered(address account, bytes32 subaccount) external view returns (bool);

    /// @notice Returns the linked signer for the account's subaccount
    /// @param account Address of the account owner
    /// @param subaccount Subaccount belonging to the account
    function getAccountLinkedSigners(address account, bytes32 subaccount) external view returns (address[] memory);

    /// @notice Returns the number of positions that the account's subaccount has open.
    /// @param account Address of the account owner
    /// @param subaccount Subaccount belonging to the account
    function getAccountOpenPositions(address account, bytes32 subaccount) external view returns (uint128);

    /// @notice Returns a pending deposit by `account` and `subaccount`.
    /// @param account Address of the account owner
    /// @param subaccount Subaccount belonging to the account
    function getAccountPendingDeposit(address account, bytes32 subaccount) external view returns (Deposit.Data memory);

    /// @notice Returns a pending withdraw by`account` and `subaccount`.
    /// @param account Address of the account owner
    /// @param withdrawDigest identifier for the withdraw, EIP712 domain digest of the withdraw data
    function getAccountPendingWithdraw(address account, bytes32 withdrawDigest)
        external
        view
        returns (Withdraw.Data memory);

    /// @notice Returns the number of registered subaccounts.
    /// @param account Address of the account owner
    function getAccountRegisteredSubaccounts(address account) external view returns (uint32);

    /// @notice Returns the `account` whose `subaccount` the signer is linked with.
    /// @param linkedSigner the active linked signer who is being searched on.
    /// @return accountLinkedToSigner when signer is active, otherwise address zero.
    function getAccountGlobalLinkedSignersToAccount(address linkedSigner) external view returns (address);

    /// @notice Returns the balance held by the exchange, sum of all accounts holdings.
    /// @param token Address of the token to retrieve the details on
    function getAccountGlobalTotalBalance(address token) external view returns (uint256);

    /// @notice Returns the total backed balance held by the exchange which include balances converted to synthetic tokens,
    /// sum of all accounts backed balances.
    /// @param token Address of the token to retrieve the details on
    function getAccountGlobalTotalBackedBalance(address token) external view returns (uint256);

    /// @notice Returns the total pending balance held by the exchange, sum of all accounts pending deposits.
    /// @param token Address of the token to retrieve the details on
    function getAccountGlobalTotalPendingBalance(address token) external view returns (uint256);

    /// @notice Returns the settlement stablecoin address.
    function getAccountGlobalUsdToken() external view returns (address);

    /// @notice Returns the amount of time , after an action is signed tha it remains valid for execution, in seconds.
    /// @param action type of action to get the buffer for
    function getExchangeActionExpiryBuffer(ActionType action) external view returns (uint64);

    /// @notice Returns the configured rescue delay in seconds.
    function getExchangeRescueDelay() external view returns (uint64);

    /// @notice Returns the timestamp of the last recorded ping.
    function getExchangeLastPingTimestamp() external view returns (uint64);

    /// @notice Returns the maximum number of deposits that a delegate depositor can submit in one batch.
    function getExchangeDelegateDepositMaxBatchSize() external view returns (uint16);

    /// @notice Returns the `account` for the PythLazer contract used for price verification.
    function getExchangePythLazer() external view returns (address pythLazer, uint64 pythMaxAge);

    /// @notice Returns true if the sequencer is approved, false otherwise.
    /// @param sequencer Sequencer address to check
    function getExchangeSequencer(address sequencer) external view returns (bool isApproved, bool isPaused);

    /// @notice Returns an array of token names.
    function getExchangeTokens() external view returns (bytes32[] memory);

    /// @notice Returns the `account` and `subaccount` that accrue the exchange fees.
    function getFeeCollector() external view returns (address feeCollectorAccount, bytes32 feeCollectorSubaccount);

    /// @notice Returns the FeeSchedule for the given id.
    function getFeeSchedule(uint32 feeScheduleId) external view returns (FeeSchedule.Data memory);

    /// @notice Returns the `account` and `subaccount` that deals with liquidated positions.
    function getLiquidator() external view returns (address liquidatorAccount, bytes32 liquidatorSubaccount);

    /// @notice Returns the token details, that was at one point supported by the exchange.
    /// @param tokenName Name of the token to retrieve the details for
    function getToken(bytes32 tokenName) external view returns (Token.Data memory);

    /// @notice Returns true if `delegator` is an approved delegate depositor, false otherwise.
    /// @param delegator Address of delegator to verify
    function isDelegateDepositor(address delegator) external view returns (bool);

    /// @notice Returns true if the exchange has been paused for deposits, withdraws and trades, false otherwise.
    function isEmergencyPaused() external view returns (bool);

    /// @notice Returns true if the account has been granted the privilege to performs an emergency pause, false otherwise.
    /// @param account Address of pauser to verify
    function isEmergencyPauser(address account) external view returns (bool);

    /// @notice Returns true if `sequencer` is an approved sequencer, false otherwise.
    /// @param sequencer Address of sequencer to verify
    function isSequencerApproved(address sequencer) external view returns (bool);

    /// @notice Returns true if the `claimer` is an approved claimer, false otherwise.
    /// @param claimer Address of the claimer to verify.
    function isClaimer(address claimer) external view returns (bool);
}
"
    },
    "src/interface/ILiquidation.sol": {
      "content": "// SPDX-License-Identifier: UNLICENSED
pragma solidity 0.8.28;

import {EngineType} from "../share/Enums.sol";
import {ActionId} from "../share/UserDefinedTypes.sol";

interface ILiquidation {
    // --- Events --- //

    /// @notice Emitted when the provided liquidation balance transfer value differs from reference calculation but within tolerance.
    event LiquidationBalanceTransferMismatch(
        ActionId id, int128 externalValue, int256 internalValue, uint256 tolerance
    );

    /// @notice Emitted when the internal maintenance margin check failed but within tolerance.
    event LiquidationMarginCheckMismatch(ActionId id, uint256 maintenanceMargin, int256 equity, uint256 tolerance);

    /// @notice Emitted when a position is transferred to liquidator due to liquidation.
    event PositionLiquidated(
        uint32 indexed productId,
        address indexed liquidatedAccount,
        bytes32 indexed liquidatedSubaccount,
        EngineType engineType,
        int128 size,
        uint128 notional,
        uint64 messageIdx
    );

    // --- Structs --- //

    struct LiquidatedProduct {
        /// Onchain productId of the liquidated position.
        uint32 productId;
        /// EngineType of product.
        EngineType engineType;
        /// Fee in wei required by Pyth to perform a price validation.
        uint64 pythFee;
        /// Size delta to liquidate e.g. position is long 0.42 then sizedelta -0.42 is required.
        int128 sizeDelta;
        /// Pyth price update blob.
        bytes pythPriceUpdate;
        /// Notional delta `size x price` as uPnL at transfer to liquidator.
        uint128 cost;
        /// Realized PnL for the liquidator from position changes.
        int128 liquidatorRealizedPnl;
    }

    struct RealizePnl {
        /// Onchain productId of the position being adjusted.
        uint32 productId;
        /// Signed change applied to the position cost to realize PnL.
        int128 costDelta;
    }

    struct LiquidateSubaccountAction {
        /// Address of liquidated trader.
        address liquidatedAccount;
        /// Subaccount of liquidated trader.
        bytes32 liquidatedSubaccount;
        /// Products with positions of liquidated trader to transfer.
        LiquidatedProduct[] products;
        /// Amount of balance transferred from the user to the liquidator beyond the positions.
        int128 balanceTransfer;
        /// Matching engine message correlation index.
        uint64 messageIdx;
    }

    struct LiquidateSubaccountWithCompensationAction {
        /// Address of liquidated trader.
        address liquidatedAccount;
        /// Subaccount of liquidated trader.
        bytes32 liquidatedSubaccount;
        /// Products with positions of liquidated trader to transfer.
        LiquidatedProduct[] products;
        /// Realized pnl snapshots provided before position transfer.
        RealizePnl[] preRealizations;
        /// Number of pre-realizations that should be applied before each liquidation in the containing `products` array entry.
        uint16[] preRealizationCounts;
        /// Amount of balance transferred from the user to the liquidator beyond the positions.
        int128 balanceTransfer;
        /// Matching engine message correlation index.
        uint64 messageIdx;
    }

    /// @notice Performs a full position takeover, transferring to the liquidator.
    /// @param id action identifier for the liquidation (useful when part of a batch operation).
    /// @param actionData the bytes of the initial payload excluding the first byte (action index).
    function liquidateSubaccount(ActionId id, bytes calldata actionData) external payable;

    /// @notice Performs a full position takeover with pre-realizations, transferring to the liquidator.
    /// @param id action identifier for the liquidation (useful when part of a batch operation).
    /// @param actionData full packed compensation action bytes, including the action header, with payload of type LiquidateSubaccountWithCompensationAction
    ///     messageIdx,
    ///     liquidatedAccount,
    ///     liquidatedSubaccount,
    ///     balanceTransfer,
    ///     numProducts,
    ///     numPreRealizations,
    ///     LiquidatedProduct[numProducts] (productId, engineType, pythFee, sizeDelta, pythPriceUpdateLength, pythPriceUpdate, cost,
    ///         liquidatorRealizedPnl),
    ///     RealizePnl[numPreRealizations] (productId, costDelta),
    ///     preRealizationCounts (length = numProducts).
    function liquidateSubaccountWithCompensation(ActionId id, bytes calldata actionData) external payable;
}
"
    },
    "src/interface/IPerpEngine.sol": {
      "content": "// SPDX-License-Identifier: UNLICENSED
pragma solidity 0.8.28;

import {OrderSide, ProductStatus} from "../share/Enums.sol";
import {ActionId} from "../share/UserDefinedTypes.sol";
import {IActionHandler} from "./IActionHandler.sol";

interface IPerpEngine {
    // --- Events --- //

    /// @notice Emitted when a perp product is registered.
    event PerpProductRegistered(uint32 indexed productId, bytes32 baseTokenName, bytes32 quoteTokenName);

    /// @notice Emitted when a perp product's Pyth feed id has been updated.
    event PerpProductPythFeedIdUpdated(uint32 indexed productId, uint32 pythFeedId);

    /// @notice Emitted when a perp product's status has been updated.
    event PerpProductStatusUpdated(uint32 indexed productId, ProductStatus status);

    /// @notice Emitted when a perp product has been updated.
    event PerpProductUpdated(uint32 indexed productId);

    /// @notice Emitted when a perp product configuration update has been initiated by the owner.
    event PerpProductUpdateInitiated(uint32 indexed productId);

    /// @notice Emitted when a pending perp product configuration update has been finalized by the sequencer.
    event PerpProductUpdateFinalized(uint32 indexed productId, uint64 messageIdx);

    /// @notice Emitted when the owner has invoked delisting for a perp product.
    event PerpProductDelistInvoked(uint32 indexed productId);

    /// @notice Emitted when the sequencer has initiated the delist context for a perp product.
    event PerpProductDelistInitiated(uint32 indexed productId, uint256 expiryPrice, uint64 messageIdx);

    /// @notice Emitted when delisting is finalized.
    event PerpProductDelistFinalized(uint32 indexed productId, uint256 expiryPrice, uint64 messageIdx);

    /// @notice Emitted when an open position on a delisting product is cash-settled.
    event PerpProductDelistPositionSettlement(
        address indexed account,
        bytes32 indexed subaccount,
        uint32 indexed productId,
        int128 size,
        int128 realizedPnl,
        uint64 messageIdx
    );

    /// @notice Emitted when a perp product's cumulative funding is updated.
    event PerpProductFundingUpdated(
        uint32 indexed productId, int256 fundingUsd, int256 cumulativeFundingUsd, uint64 messageIdx
    );

    /// @notice Emitted when a perp product's cumulative position fee is updated.
    event PerpProductPositionFeeUpdated(
        uint32 indexed productId,
        uint128 positionFeeDeltaUsd,
        uint128 cumulativePositionFeeUsd,
        uint256 liquidatorCreditAmount,
        uint64 messageIdx
    );

    /// @notice Emitted when a fill notional mismatch is detected.
    event PerpFillNotionalMismatch(ActionId id, uint128 externalValue, uint128 internalValue, uint128 tolerance);

    /// @notice Emitted when two orders in a perp product match.
    event PerpOrderMatched(
        uint32 indexed productId,
        address indexed maker,
        address indexed taker,
        bytes32 makerSubaccount,
        bytes32 takerSubaccount,
        OrderSide makerSide,
        OrderSide takerSide,
        uint128 fillQuantity,
        uint128 price,
        uint128 makerFee,
        uint128 takerFee,
        uint64 messageIdx
    );

    /// @notice Emitted when funding for positions held by `account/subaccount` is realized.
    event PerpFundingRealized(
        address indexed account,
        bytes32 indexed subaccount,
        uint32[] productIds,
        int256 realizedFundingUsd,
        uint64 messageIdx
    );

    /// @notice Emitted when PnL for a position is realized ad-hoc.
    event PerpPnlRealized(
        address indexed account,
        bytes32 indexed subaccount,
        uint32 indexed productId,
        int128 costDelta,
        uint64 messageIdx
    );

    // --- Structs --- //

    /// @notice Params used to register a perp product.
    struct RegisterPerpProductParams {
        bytes32 baseTokenName;
        bytes32 quoteTokenName;
        ProductStatus status;
        uint16 maxLeverage;
        uint32 feeScheduleId;
        uint32 pythFeedId;
        uint128 tickSize;
        uint128 maxQuantity;
        uint128 lotSize;
        uint128 maxOpenInterestUsd;
        uint128 maxPositionNotionalUsd;
    }

    /// @notice Params used to update a perp product.
    struct UpdatePerpProductParams {
        uint32 id;
        uint16 maxLeverage;
        uint128 maxQuantity;
        uint128 maxOpenInterestUsd;
        uint128 maxPositionNotionalUsd;
    }

    struct ExecuteMatchDigests {
        bytes32 maker; // Hash of the EIP-712 maker message
        bytes32 taker; // Hash of the EIP-712 taker message
    }

    /// @dev Data structure to hold the fill data for a position settlement.
    struct FillData {
        uint128 quantity;
        uint128 price;
        int128 oldSize;
        int128 newSize;
        int128 sizeDelta;
    }

    /// @dev Data structure to hold the fill data for a position settlement from an external source.
    struct ExternalFillData {
        uint128 eFillNotional;
        int128 eRealizedPnl;
    }

    /// @notice Initiates a sequencer-delivered delist context for a perp product.
    /// @param id Id of the initiate delist action in the `processActions` array
    /// @param action Action containing product id, engine message index, and Pyth price update
    function initiateDelist(ActionId id, IActionHandler.InitiatePerpProductDelistAction calldata action)
        external
        payable;

    /// @notice Cash-settles a single open position during a product delist.
    /// @param id Id of the settle action in the `processActions` array
    /// @param action Settlement action with account/subaccount/productId, engine-reported realized PnL,
    ///               expiry price, and engine message index
    function settleDelistPosition(ActionId id, IActionHandler.PerpProductDelistPositionSettlementAction calldata action)
        external
        payable;

    /// @notice Finalizes a perp product delist after all positions have been settled and open interest is zero.
    /// @param id Id of the finalize delist action in the `processActions` array
    /// @param action Action containing product id and engine message index
    function finalizeDelist(ActionId id, IActionHandler.FinalizePerpProductDelistAction calldata action)
        external
        payable;

    /// @notice Finalizes and applies a pending product update.
    /// @param id Id of the finalize action in the `processActions` array
    /// @param action The sequencer-finalized pending product update
    function finalizeUpdate(ActionId id, IActionHandler.FinalizePerpProductUpdateAction calldata action)
        external
        payable;

    /// @notice Match a maker and take order by its product.
    /// @param id Id of the match action in the `processActions` array
    /// @param action The match action containing maker and taker orders with signatures and fees
    /// @param digests Digests of the EIP-712 maker and taker messages
    function executeMatch(
        ActionId id,
        IActionHandler.MatchOrdersAction calldata action,
        ExecuteMatchDigests calldata digests
    ) external payable;

    /// @notice Updates a perp product's funding, adding `cumulativeFundingUsd`.
    /// @param id Id of the update funding action in the `processActions` array
    /// @param productId Id of the product to update funding on
    /// @param cumulativeFundingUsd Funding USD delta to update with
    /// @param messageIdx Message index that produced funding update
    function updateFunding(ActionId id, uint32 productId, int128 cumulativeFundingUsd, uint64 messageIdx)
        external
        payable;

    /// @notice Updates a perp product's position fee, adding `positionFeeDeltaUsd`.
    /// @param id Id of the update position fee action in the `processActions` array
    /// @param productId Id of the product to update position fee on
    /// @param positionFeeDeltaUsd Position fee USD delta to update with
    /// @param liquidatorCreditAmount Amount to credit to the configured liquidator
    /// @param messageIdx Message index that produced position fee update
    function updatePositionFee(
        ActionId id,
        uint32 productId,
        uint128 positionFeeDeltaUsd,
        uint256 liquidatorCreditAmount,
        uint64 messageIdx
    ) external payable;

    /// @notice Realizes funding for a list of products for a specific account/subaccount.
    /// @param id Id of the realize funding action in the `processActions` array
    /// @param account Address to realize funding for (cannot be a signer)
    /// @param subaccount Subaccount to realize funding for
    /// @param productIds Sorted (asc) list of all productIds with open positions
    /// @param messageIdx Message index that produced this action
    /// @dev This function will no-op if all parameters are valid but positions are fresh or funding is net zero.
    function realizeFunding(
        ActionId id,
        address account,
        bytes32 subaccount,
        uint32[] calldata productIds,
        uint64 messageIdx
    ) external payable;

    /// @notice Realizes PnL by adjusting position cost and user balance.
    /// @param id Id of the realize pnl action in the `processActions` array
    /// @param account Address of the account holding the position
    /// @param subaccount Subaccount holding the position
    /// @param productId Product ID of the position to realize PnL for
    /// @param costDelta Cost adjustment to apply to position and balance
    /// @param messageIdx Message index that produced this action
    function realizePnl(
        ActionId id,
        address account,
        bytes32 subaccount,
        uint32 productId,
        int128 costDelta,
        uint64 messageIdx
    ) external payable;
}
"
    },
    "src/lib/ActionDecoder.sol": {
      "content": "// SPDX-License-Identifier: MIT
pragma solidity 0.8.28;

import {IActionHandler} from "../interface/IActionHandler.sol";
import {IDeleverage} from "../interface/IDeleverage.sol";
import {ILiquidation} from "../interface/ILiquidation.sol";
import {EngineType, OrderSide} from "../share/Enums.sol";
import {ActionType} from "../share/Enums.sol";
import {InvalidActionEncoding, InvalidActionEncodingHeader} from "../share/Errors.sol";
import {ActionId} from "../share/UserDefinedTypes.sol";

library ActionDecoder {
    uint8 private constant ACTION_ID_SIZE_BYTES = 8;

    // actionHeaderOffset = bytesSizeUint64 + bytesSizeUint8
    uint8 private constant ACTION_HEADER_OFFSET = 9;

    // --- MatchOrders indexes --- //

    // makerSenderIndex = bytesSizeUint64 + bytesSizeUint8
    uint16 private constant MATCH_ORDER_MAKER_SENDER = 9;
    // makerSubaccountIndex = makerSenderIndex + bytesSizeAddress
    uint16 private constant MATCH_ORDER_MAKER_SUBACCOUNT = 29;
    // makerQuantityIndex = makerSubaccountIndex + bytesSizeBytes32
    uint16 private constant MATCH_ORDER_MAKER_QUANTITY = 61;
    // makerPriceIndex = makerQuantityIndex + bytesSizeUint128
    uint16 private constant MATCH_ORDER_MAKER_PRICE = 77;
    // makerReduceOnlyIndex = makerPriceIndex + bytesSizeUint128
