            pos += 2;

            // Read matches
            result.users[u].matches = new IDeleverage.DeleverageUserMatchPacked[](numMatches);
            for (uint16 m = 0; m < numMatches; m++) {
                // productIndex (2 bytes)
                result.users[u].matches[m].productIndex = uint16(bytes2(action[pos:pos + 2]));
                pos += 2;

